// describeSyncRemote explains that only one of several remotes carries
// checkpoints, and how reads follow it back. Silent when nothing was elected,
// so the note never names a destination the push side would not use.
func (t remoteTopology) describeSyncRemote(w io.Writer) {
	if t.syncRemote == "" {
		return
	}
	fmt.Fprintf(w, "    Checkpoints sync to %q only%s.\n", t.syncRemote, syncRemoteSourceSuffix(t.syncSource))
	fmt.Fprintln(w, "    Pushing to any other remote sends your code but no session history.")
	// The read chain is the elected remote followed by origin as a read-only
	// legacy tier — and only when origin exists, so a fork/upstream repo is
	// never told to fall back to a remote it does not have.
	if t.syncRemote != originRemoteName && t.hasRemote(originRemoteName) {
		fmt.Fprintf(w, "    Reading them back (resume, explain) checks %q first, then origin.\n", t.syncRemote)
	} else {
		fmt.Fprintln(w, "    Reading them back (resume, explain) looks there too.")
	}
	fmt.Fprintln(w, "    To change that, set strategy_options.checkpoint_push_remote to a remote")
	fmt.Fprintln(w, "    name; pushes and reads both follow it.")
}

// syncRemoteSourceSuffix names the tier that elected the sync remote, for the
// two tiers a user can act on. Phrasing matches `entire status` so the same
// fact reads the same way in both places.
func syncRemoteSourceSuffix(source strategy.CheckpointSyncRemoteSource) string {
	switch source {
	case strategy.SyncRemoteSourceConfig:
		return " (set by checkpoint_push_remote)"
	case strategy.SyncRemoteSourceCaptured:
		return " (captured from your pushes)"
	case strategy.SyncRemoteSourceDefault, strategy.SyncRemoteSourceSole, strategy.SyncRemoteSourceFirst:
		// Fallback tiers: naming them would explain the CLI's precedence rules
		// rather than the user's repo, and the next line already says how to
		// take the choice over.
		return ""
	default:
		return ""
	}
}

// hasRemote reports whether a remote of this name is configured.

