// describeSyncRemote explains that only one of several remotes carries
// checkpoints, and how reads follow it back. Silent when nothing was elected,
// so the note never names a destination the push side would not use.
//
// The unsettled tiers get an extra sentence because naming today's remote is
// not the whole truth: on the default/first-in-config tiers the election is
// still open, and the first push that agrees with the branch's declared push
// destination captures that remote instead — carrying the checkpoints with it
// (see strategy.maybeCaptureCheckpointSyncRemote, which runs before the
// single-remote gate). Saying "checkpoints go to origin" full stop would be a
// promise the next push can break.
func (t remoteTopology) describeSyncRemote(w io.Writer) {
	if t.syncRemote == "" {
		return
	}
	settled := t.syncSource == strategy.SyncRemoteSourceConfig || t.syncSource == strategy.SyncRemoteSourceCaptured

	fmt.Fprintf(w, "    Checkpoints sync to %q only%s.\n", t.syncRemote, syncRemoteSourceSuffix(t.syncSource))
	if !settled {
		fmt.Fprintln(w, "    That is not settled yet: the first push to the remote your branch is")
		fmt.Fprintln(w, "    configured to push to moves checkpoints there for good, and says so.")
	}
	// The read chain is the elected remote followed by origin as a read-only
	// legacy tier — and only when origin exists, so a fork/upstream repo is
	// never told to fall back to a remote it does not have.
	if t.syncRemote != originRemoteName && t.hasRemote(originRemoteName) {
		fmt.Fprintf(w, "    Reads (resume, explain) check %q first, then origin.\n", t.syncRemote)
	} else {
		fmt.Fprintln(w, "    Reads (resume, explain) follow the same remote.")
	}
	// A repo that already set checkpoint_push_remote is told nothing about it:
	// the decision is made, and repeating the key would read as a warning that
	// something still needs doing.
	switch t.syncSource {
	case strategy.SyncRemoteSourceConfig:
	case strategy.SyncRemoteSourceCaptured:
		fmt.Fprintln(w, "    To move it, set strategy_options.checkpoint_push_remote to a remote name.")
	default:
		fmt.Fprintln(w, "    To decide it yourself, set strategy_options.checkpoint_push_remote to a")
		fmt.Fprintln(w, "    remote name; pushes and reads both follow it, and capture stops.")
	}
}

